bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
python3 - <<'PY'
import json,os,subprocess,sys,time
from pathlib import Path
CHAT=-1002373696859
TARGETS={1605:([4637,4621,4607],4621),1634:([4625,4611,4597],4625),1723:([4695],4695)}
LEDGER=Path("deploy/state/startless-video-specialists-only-withdraw-20261122")
def run(args,input=None,timeout=120):
 return subprocess.run(args,input=input,capture_output=True,text=True,timeout=timeout)
def db(q):
 r=run(["docker","exec","deploy-postgres-1","psql","-X","-q","-v","ON_ERROR_STOP=1","-U","gace","-d","gaybbs","-Atc",q],timeout=30)
 if r.returncode:raise RuntimeError("DB_ERROR")
 return r.stdout.strip()
def audit(topic):
 r=run(["python3","scripts/userbot_topic_audit_client.py","--chat-id",str(CHAT),"--topic-id",str(topic)],timeout=125)
 if r.returncode:raise RuntimeError("AUDIT_FAILED")
 x=[json.loads(s.split("=",1)[1]) for s in r.stdout.splitlines() if s.startswith("USERBOT_TOPIC_AUDIT=")]
 if len(x)!=1 or len(x[0].get("rows",[]))!=1:raise RuntimeError("AUDIT_RESPONSE")
 return x[0]["rows"][0]
def persist(file,obj,first=False):
 dest=file if first else file.with_suffix(".next")
 with os.fdopen(os.open(dest,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600),"w") as f:
  json.dump(obj,f,sort_keys=True);f.flush();os.fsync(f.fileno())
 if not first:os.replace(dest,file)
node=r"""
'use strict';
const fs=require('node:fs'),https=require('node:https');
const token=fs.readFileSync(process.env.BOT_TOKEN_FILE||'/run/secrets/bot_token','utf8').trim(),t=__TASK_JSON__;
const agent=new https.Agent({family:4,keepAlive:false,timeout:20000});
function api(name,data){return new Promise((resolve,reject)=>{const b=JSON.stringify(data);
 const req=https.request({hostname:'api.telegram.org',path:'/bot'+token+'/'+name,method:'POST',agent,timeout:25000,
 headers:{'Content-Type':'application/json','Content-Length':Buffer.byteLength(b)}},res=>{
 let s='';res.on('data',x=>{if(s.length<16000)s+=x});res.on('end',()=>{
 try{const v=JSON.parse(s);resolve(v.ok?{ok:true,val:v.result}:{ok:false,code:v.error_code})}
 catch{reject(Error('BAD_RESPONSE'))}})});
 req.on('error',()=>reject(Error('UNCERTAIN_TRANSPORT')));req.on('timeout',()=>req.destroy(Error('UNCERTAIN_TIMEOUT')));req.end(b)})}
(async()=>{const me=await api('getMe',{});
 if(!me.ok||me.val.username?.toLowerCase()!=='gaybbs_bot'||me.val.id===8086265383)throw Error('WRONG_BOT');
 if(t.mode==='identity'){console.log(JSON.stringify({state:'BOT_OK'}));return}
 if(t.mode!=='remove_markup'||t.chat!==-1002373696859||!Number.isInteger(t.mid)||t.mid<1)throw Error('INVALID_ACTION');
 const edit=await api('editMessageReplyMarkup',{chat_id:t.chat,message_id:t.mid});
 console.log(JSON.stringify({state:edit.ok?'MARKUP_REMOVED':'EDIT_DENIED',code:edit.ok?null:edit.code}));
 if(!edit.ok)process.exitCode=2;
})().catch(e=>{console.log(JSON.stringify({state:'EDIT_UNKNOWN',kind:String(e.message||'UNKNOWN')}));process.exitCode=3});
"""
def bot(task):
 r=run(["docker","exec","-i","deploy-gaybbs-1","node","-"],input=node.replace("__TASK_JSON__",json.dumps(task)),timeout=90)
 try:
  d=[json.loads(x) for x in r.stdout.splitlines() if x.startswith("{")]
  return r.returncode,d[0] if len(d)==1 else {"state":"UNKNOWN"}
 except:return r.returncode,{"state":"UNKNOWN"}
if run(["systemctl","--user","is-active","gace-userbot-verify.service"]).stdout.strip()!="active":sys.exit(60)
if run(["docker","inspect","-f","{{.State.Running}}","deploy-gaybbs-1"]).stdout.strip()!="true":sys.exit(61)
c,ident=bot({"mode":"identity"});assert c==0 and ident.get("state")=="BOT_OK"
for topic,(ids,primary) in TARGETS.items():
 if (LEDGER/str(topic)).exists():sys.exit(62)
 if db(f"SELECT message_id,state,pinned FROM topic_dm_entry_pins WHERE chat_id={CHAT} AND message_thread_id={topic}")!=f"{primary}|published|t":sys.exit(63)
 row=audit(topic)
 if row.get("post_button")!="PRESENT" or row.get("pin_message_ids")!=[] or row.get("history_message_ids")!=ids or row.get("button_types")!=["normal"]:sys.exit(64)
LEDGER.mkdir(parents=True,exist_ok=True,mode=0o700)
for topic,(ids,primary) in TARGETS.items():
 d=LEDGER/str(topic);d.mkdir(mode=0o700)
 for mid in ids:
  f=d/(str(mid)+".json")
  row=audit(topic)
  if mid not in row.get("history_message_ids",[]):sys.exit(65)
  persist(f,{"state":"EDIT_ATTEMPTING","topic_id":topic,"message_id":mid},first=True)
  code,result=bot({"mode":"remove_markup","chat":CHAT,"mid":mid})
  if code or result.get("state")!="MARKUP_REMOVED":
   persist(f,{"state":result.get("state","UNKNOWN"),"topic_id":topic,"message_id":mid})
   sys.exit(66)
  persist(f,{"state":"MARKUP_REMOVED_ACK","topic_id":topic,"message_id":mid})
 row=audit(topic)
 if row.get("post_button")!="ABSENT" or row.get("history_message_ids")!=[]:sys.exit(67)
 r=db(f"UPDATE topic_dm_entry_pins SET state='needs_reconcile',pinned=FALSE,updated_at=NOW() WHERE chat_id={CHAT} AND message_thread_id={topic} AND message_id={primary} AND state='published' AND pinned=TRUE RETURNING message_id")
 if r!=str(primary):sys.exit(68)
 for mid in ids:
  f=d/(str(mid)+".json")
  persist(f,{"state":"VERIFIED_DISABLED_BY_MASTER","topic_id":topic,"message_id":mid,"original_post_preserved":True})
 print("VIDEO_TOPIC_"+str(topic)+"_HISTORIC_BUTTONS_WITHDRAWN="+str(len(ids)))
if run(["systemctl","--user","is-active","gace-userbot-verify.service"]).stdout.strip()!="active":sys.exit(69)
print("VIDEO_UNAPPROVED_SEVEN_MARKUPS_REMOVED=VERIFIED;NO_MESSAGES_DELETED=YES")
PY
